5	/** The claim form's rules, shared by the steps that add claims one at a time and many at once. */
6	public final class ClaimRules {
7	
8	    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
9	
10	    private static final Pattern NUMBER = Pattern.compile("(.+-)?\\d{1,9}");
11	
12	    private ClaimRules() {
13	    }
