15	    /** Checks one claim form's fields as ValidateClaim does; a null field is blank. */
16	    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField)
17	            throws InvalidClaimException {
18	        String amount = amountField == null ? "" : amountField.trim();
19	        String date = dateField == null ? "" : dateField.trim();
20	        String note = noteField == null ? "" : noteField.trim();
21	        String corrects = correctsField == null ? "" : correctsField.trim();
22	        if (!AMOUNT.matcher(amount).matches()) {
23	            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
24	        }
25	        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
26	            throw new InvalidClaimException("Corrects must be a claim number.");
27	        }
28	        BigDecimal value = new BigDecimal(amount).setScale(2);
29	        if (value.signum() < 0 && corrects.isEmpty()) {
30	            throw new InvalidClaimException("A negative amount is a correction: name the settled claim it corrects.");
31	        }
32	        if (value.signum() >= 0 && !corrects.isEmpty()) {
33	            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
34	        }
35	        LocalDate parsed = null;
36	        if (!date.isEmpty()) {
37	            try {
38	                parsed = LocalDate.parse(date);
39	            } catch (DateTimeParseException e) {
40	                throw new InvalidClaimException("Not a date: " + date);
41	            }
42	        }
43	        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects);
44	    }
