46	    /** The claim the input makes for the person, not yet saved; refused as BuildClaim refuses it. */
47	    public static Claim make(ClaimInput input, Sheet sheet, Person person, ClaimRepository repository,
48	            PeriodRepository periods, PersonGradeRepository grades) throws InvalidClaimException {
49	        LocalDate date = input.date() != null ? input.date() : sheet.getToday();
50	        if (periods.isClosedOn(sheet.getId(), date)) {
51	            throw new InvalidClaimException("No claim can be added in a closed period.");
52	        }
53	        if (person.retiredOn(date)) {
54	            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
55	        }
56	        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), person.getId(), input.corrects());
57	        Claim claim = new Claim(sheet.getId(), person.getId(), input.amount(), date, input.note(), input.corrects());
58	        claim.setCorrectsDate(correctsDate);
59	        claim.setDueBy(date.plusDays(sheet.termsFor(grades.gradesOf(person).on(date), date)));
