77	/**
78	 * The figures of one person's claims, as the screen works them out: a settled claim's frozen due, else the
79	 * figure its person's last statement bound it to (not while PENDING), else its live due (amount times the rate in force on its date of
80	 * the grade its person had on its date, rounded by the sheet's policy, and at least the sheet's floor in force on its date; none — n/a — when no rate applies then, or the one that would has ended by then). An
81	 * overdue claim's due adds, on top of its figure, the late charge: the sheet's late percent in force on its date of the figure for every
82	 * full 30 days it is overdue on the sheet's today, rounded like a due. A statement never binds the charge; settling
83	 * freezes it in. A correction's live due is its amount times the rate, rounded the same way, with no floor, and it
84	 * never takes a late charge. The rounding policy: a claim dated before the sheet's policy date (its today when blank)
85	 * rounds half up, one dated on or after it half to even; a correction goes by the date of the claim it corrects.
86	 */
87	public class ClaimFigures {
88	
89	    private final List<Rate> rates;
90	
91	    private final PersonGrades grades;
92	
93	    private final Sheet sheet;
94	
95	    private final LocalDate today;
96	
97	    private final LocalDate policyDate;
98	
99	    private final BigDecimal cap;
100	
101	    /** @param rates the sheet's rates.
102	     *  @param grades the person's grades over time.
103	     *  @param sheet the sheet: its floor on a claim's date (a live due is at least it), and its late percent on a
104	     *  claim's date and its today (the late charge), and its cap in force on its today. */
105	    public ClaimFigures(List<Rate> rates, PersonGrades grades, Sheet sheet) {
106	        this.rates = rates;
107	        this.grades = grades;
108	        this.sheet = sheet;
109	        this.today = sheet.getToday();
110	        this.policyDate = sheet.policyDateInForce();
111	        this.cap = sheet.getCap();
112	    }
113	
114	    /** How the claim's live figures round: half up when the date it rounds by is before the policy date, else half
115	     *  to even. */
116	    public RoundingMode rounding(Claim claim) {
117	        return claim.getRoundsOn().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
118	    }
119	
120	    /** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by (fixed when it was created) is
121	     *  before the sheet's today. */
122	    public boolean overdue(Claim claim) {
123	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && claim.getDueBy().isBefore(today);
124	    }
125	
126	    /** The late charge on a figure: the late percent of it for every full 30 days the claim is overdue, rounded
127	     *  like its due; 0.00 when it is not overdue. */
128	    public BigDecimal lateCharge(Claim claim, BigDecimal figure) {
129	        if (figure == null || claim.isCorrection() || !overdue(claim)) {
130	            return BigDecimal.ZERO.setScale(2);
131	        }
132	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), today) / 30;
133	        return figure.multiply(sheet.latePctOn(claim.getDate())).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
134	                .setScale(2, rounding(claim));
135	    }
136	
137	    /** A live due: the amount times the percent, divided by 100, rounded as given, and at least the floor. */
138	    public static BigDecimal liveDue(BigDecimal amount, BigDecimal pct, BigDecimal floor, RoundingMode rounding) {
139	        BigDecimal due = amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
140	        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
141	    }
142	
143	    /** Whether a claim counts toward the totals on a day: only OPEN, PENDING and SETTLED claims do, but not an OPEN
144	     *  one deferred until after that day. */
145	    public static boolean counts(Claim claim, LocalDate today) {
146	        return (claim.getStatus().isOpen() || claim.getStatus() == ClaimStatus.SETTLED) && !claim.isDeferredOn(today);
147	    }
148	
149	    /** Whether a claim counts toward the live totals: as {@link #counts}, except its person's OPEN and PENDING
150	     *  claims dated within a hold of theirs, unless a statement binds them (null person: no holds). */
151	    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
152	        return counts(claim, today) && !(person != null && claim.getStatus().isOpen() && !claim.isBound()
153	                && person.heldOn(claim.getDate()));
154	    }
155	
156	    /** The percent of the grade's rate in force on a date; none when that rate's to-date is before it. */
157	    private Optional<BigDecimal> rateOn(String grade, LocalDate on) {
158	        return rates.stream()
159	                .filter(r -> r.getGrade().equals(grade))
160	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(on))
161	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
162	                .filter(r -> !r.endedBy(on))
163	                .map(Rate::getPct);
164	    }
165	
166	    /** The due the claim would have today as an open claim bound by no statement: its live figure at today's rates,
167	     *  grades and floor, plus the late charge it would carry as an open claim; null when it has none (n/a). */
168	    public BigDecimal openDue(Claim claim) {
169	        BigDecimal figure = liveFigure(claim);
170	        if (figure == null) {
171	            return null;
172	        }
173	        if (claim.isCorrection() || !claim.getDueBy().isBefore(today)) {
174	            return figure;
175	        }
176	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), today) / 30;
177	        return figure.add(figure.multiply(sheet.latePctOn(claim.getDate())).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
178	                .setScale(2, rounding(claim)));
179	    }
180	
181	    /** The claim's due: its figure, plus the late charge while it is not settled; null when it has none (n/a). */
182	    public BigDecimal due(Claim claim) {
183	        if (claim.getDue() != null) {
184	            return claim.getDue();
185	        }
186	        BigDecimal figure = figure(claim);
187	        return figure == null ? null : figure.add(lateCharge(claim, figure));
188	    }
189	
190	    /** The claim's figure, without any late charge; null when it has none (n/a). */
191	    public BigDecimal figure(Claim claim) {
192	        if (claim.getDue() != null) {
193	            return claim.getDue();
194	        }
195	        if (claim.isBound()) {
196	            return claim.getStatedDue();
197	        }
198	        return liveFigure(claim);
199	    }
200	
201	    /** The claim's live figure: neither frozen nor bound; null when it has none (n/a). */
202	    private BigDecimal liveFigure(Claim claim) {
203	        return rateOn(grades.on(claim.getDate()), claim.getDate())
204	                .map(pct -> liveDue(claim.getAmount(), pct, claim.isCorrection() ? null : sheet.floorOn(claim.getDate()), rounding(claim)))
205	                .orElse(null);
206	    }
207	
208	    /** The person's due-total: their counted claims' dues (with any late charge) added up, 0.00 with none; n/a when their grade
209	     *  in force on the day has no rate in force then, unless a counted claim keeps a figure: a fixed one (settled or bound), or a
210	     *  live one at another grade they had on its date, or one dated on or before the day (at a rate that has ended since). */
211	    public String dueTotal(List<Claim> claims, LocalDate today) {
212	        return dueTotal(claims, today, null);
213	    }
214	
215	    /** The person's live due-total, as {@link #dueTotal(List, LocalDate)}; their OPEN claims dated within a hold
216	     *  of theirs do not count, unless a statement binds them. At most the sheet's cap (n/a is not capped). */
217	    public String dueTotal(List<Claim> claims, LocalDate today, Person person) {
218	        String sum = uncappedDueTotal(claims, today, person);
219	        if (cap == null || "n/a".equals(sum) || new BigDecimal(sum).compareTo(cap) <= 0) {
220	            return sum;
221	        }
222	        return cap.setScale(2).toPlainString();
223	    }
224	
225	    /** The person's live due-total before the cap: the sum of their figures. */
226	    private String uncappedDueTotal(List<Claim> claims, LocalDate today, Person person) {
227	        List<Claim> counted = claims.stream().filter(c -> countsLive(c, person, today)).toList();
228	        String grade = grades.on(today);
229	        boolean kept = counted.stream().anyMatch(c -> c.getDue() != null || (c.isBound() && c.getStatedDue() != null)
230	                || (!c.isBound() && (!grade.equals(grades.on(c.getDate())) || !c.getDate().isAfter(today)) && figure(c) != null));
231	        if (rateOn(grade, today).isEmpty() && !kept) {
232	            return "n/a";
233	        }
234	        return counted.stream().map(this::due).filter(f -> f != null)
235	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
236	    }
237	}
