469	/**
470	 * A claim's status: it starts DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling one above the
471	 * clerk limit leaves it PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A DRAFT, OPEN or
472	 * PENDING claim can be voided (VOID). SETTLED and VOID are final. Only OPEN, PENDING and SETTLED claims count toward
473	 * totals.
474	 */
475	public enum ClaimStatus {
476	    DRAFT, OPEN, PENDING, SETTLED, VOID;
477	
478	    /** The status an action ("open", "settle", "approve", "reject", "void") moves this one to, or null when it is not
479	     *  allowed. A settle above the clerk limit by a clerk ends in PENDING instead. */
480	    public ClaimStatus after(String action) {
481	        return switch (action) {
482	            case "open" -> this == DRAFT ? OPEN : null;
483	            case "settle" -> this == OPEN ? SETTLED : null;
484	            case "approve" -> this == PENDING ? SETTLED : null;
485	            case "reject" -> this == PENDING ? OPEN : null;
486	            case "void" -> this == DRAFT || this == OPEN || this == PENDING ? VOID : null;
487	            default -> null;
