571	 * the claim the sheet's next number (or, while the sheet's period numbering is on, the next in its period: <period>-<n>,
572	 * X-<n> for a claim in no period) and records who opened it; a voided claim keeps its number (never reused). The one who opened a
573	 * claim cannot settle it, and a clerk (any name not made a steward) settles a claim only when its due is at or below
574	 * the sheet's clerk limit (a due of n/a is within any limit; no limit when the sheet has none): a clerk settling one
575	 * above it leaves it PENDING instead. Only a steward approves a PENDING claim (it is settled, its due fixed at its live
576	 * figure then) or rejects it, with a reason that is not blank (it is OPEN again); the one who opened it cannot approve it. Settling fixes the claim's due at the rate of the grade its
577	 * person had on the claim's date, in force on the claim's date, at least the sheet's floor (or at the figure its person's last statement bound it to), plus its late charge on the sheet's today (none when no rate applies then, so it stays live). A claim deferred until after the sheet's today cannot be settled. A claim dated in a closed period cannot change status. Returns the claim's number for the
578	 * audit.
579	 */
580	public class ApplyClaimStatus {
581	    public String apply(@PathVariable("action") String action, @Val Claim claim, ClaimRepository repository,
582	            EntityManager entityManager, PersonRepository people, RateRepository rates, PersonGradeRepository grades, PeriodRepository periods,
583	            @Val Sheet sheet, RoleRepository roles,
584	            @RequestHeader(name = "X-User", required = false) String userHeader,
585	            @RequestParam(name = "reason", required = false) String reason) throws ClaimStatusException, ClerkLimitException {
586	        String user = AuditUser.decode(userHeader);
587	        if (periods.isClosedOn(claim.getSheetId(), claim.getDate())) {
588	            throw new ClaimStatusException("A claim in a closed period cannot change status.");
589	        }
590	        if ("open".equals(action) && claim.getStatus().after(action) != null) {
591	            // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent open is seen.
592	            boolean perPeriod = sheet.periodNumberingOn();
593	            if (perPeriod) {
594	                repository.lockSheet(claim.getSheetId());
595	            } else {
596	                repository.takeNextNumber(claim.getSheetId());
597	            }
598	            entityManager.refresh(claim);
599	            ClaimStatus next = check(claim, action);
600	            if (perPeriod) {
601	                String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
602	                        .filter(p -> p.contains(claim.getDate())).map(Period::getName).findFirst().orElse(null);
603	                String seq = prefix == null ? "X" : "P:" + prefix;
604	                claim.setNumber((prefix == null ? "X" : prefix) + "-" + repository.takeNextInSequence(claim.getSheetId(), seq));
605	            } else {
606	                claim.setNumber(String.valueOf(repository.lastNumber(claim.getSheetId())));
607	            }
608	            claim.setStatus(next);
609	            claim.setOpenedBy(user);
610	        } else {
611	            ClaimStatus next = check(claim, action);
612	            boolean steward = Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user));
613	            if (("approve".equals(action) || "reject".equals(action)) && !steward) {
614	                throw new ClerkLimitException("Only a steward can approve or reject a pending claim.");
615	            }
616	            if ("reject".equals(action) && (reason == null || reason.isBlank())) {
617	                throw new ClaimStatusException("A rejection needs a reason.");
618	            }
619	            if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
620	                throw new ClaimStatusException("A deferred claim cannot be settled until the sheet's today reaches its date.");
621	            }
622	            if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
623	                throw new ClaimStatusException("The one who opened a claim cannot settle or approve it.");
624	            }
625	            if (next == ClaimStatus.SETTLED) {
626	                BigDecimal due = people.findById(claim.getPersonId())
627	                        .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
628	                                grades.gradesOf(p), sheet).due(claim))
629	                        .orElse(null);
630	                BigDecimal limit = sheet.getClerkLimit();
631	                if ("settle".equals(action) && limit != null && due != null && due.compareTo(limit) > 0 && !steward) {
632	                    next = ClaimStatus.PENDING;
633	                } else {
634	                    claim.setDue(due);
635	                }
636	            }
637	            claim.setStatus(next);
638	        }
639	        repository.saveAndFlush(claim);
640	        return claim.getNumber();
641	    }
642	
643	    private static ClaimStatus check(Claim claim, String action) throws ClaimStatusException {
644	        ClaimStatus next = claim.getStatus().after(action);
645	        if (next == null) {
646	            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot " + action + ".");
647	        }
648	        return next;
649	    }
650	}
