701	            RateRepository rates, SheetRepository sheets, PersonGradeRepository grades) throws InvalidPeriodException {
702	        if (period.isClosed()) {
703	            throw new InvalidPeriodException("The period is already closed.");
704	        }
705	        Sheet sheet = sheets.findById(period.getSheetId()).orElseGet(() -> new Sheet(period.getSheetId()));
706	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(period.getSheetId()).stream()
707	                .collect(Collectors.toMap(Person::getId, Function.identity()));
708	        var sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(period.getSheetId());
709	        Map<Long, List<PersonGrade>> dated = grades.datedOnSheet(period.getSheetId());
710	        Map<Long, BigDecimal> totals = new HashMap<>();
711	        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
712	        claims.findBySheetIdOrderByIdDesc(period.getSheetId()).stream()
713	                .filter(c -> byId.containsKey(c.getPersonId()) && ClaimFigures.countsLive(c, byId.get(c.getPersonId()), sheet.getToday())
714	                        && period.contains(c.getDate()))
715	                .forEach(c -> {
716	                    BigDecimal due = new ClaimFigures(sheetRates, new PersonGrades(byId.get(c.getPersonId()).getGrade(),
717	                            dated.getOrDefault(c.getPersonId(), List.of())), sheet).due(c);
718	                    if (due != null) {
