596	/**
597	 * Takes a statement for the person: records their due-total now, on the sheet's today, and binds each of
598	 * their claims that counts to the figure it has now (never its late charge, which keeps following the sheet's today); their claims that do not count (a person's unbound OPEN ones dated within a
599	 * hold among them) are unbound (live again).
600	 */
601	public class TakeStatement {
602	    public void take(@Val Sheet sheet, @Val Person person, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades,
603	            StatementRepository statements, EntityManager entityManager, Out<Statement> statementOut) {
604	        // Lock the person so two statements (or a statement and an edit) are taken one after the other.
605	        entityManager.refresh(person, LockModeType.PESSIMISTIC_WRITE);
606	        List<Claim> mine = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheet.getId(), person.getId());
607	        ClaimFigures figures = new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheet.getId()),
608	                grades.gradesOf(person), sheet);
609	        String dueTotal = figures.dueTotal(mine, sheet.getToday(), person);
610	        int counted = 0;
611	        for (Claim claim : mine) {
612	            if (ClaimFigures.countsLive(claim, person, sheet.getToday())) {
613	                BigDecimal figure = figures.figure(claim);
614	                claim.bind(true, figure);
615	                counted++;
616	            } else {
617	                claim.bind(false, null);
618	            }
619	        }
620	        claims.saveAllAndFlush(mine);
621	        statementOut.set(statements.save(
622	                new Statement(sheet.getId(), person.getId(), dueTotal, sheet.getToday(), counted)));
623	    }
624	}
