637	/**
638	 * The sheet's figures at one moment, as the screen shows them: each person's claimed and due-total, in the
639	 * order they were added, and the sheet's claimed-total and due-total (everyone's added up, skipping n/a), and each
640	 * person's and the sheet's overdue-total (their counted overdue claims' dues, with late charge, skipping n/a).
641	 * A person's OPEN and PENDING claims dated within a hold of theirs count in none of them, unless a statement binds them.
642	 */
643	public class Rollup {
644	    /** One person's figures. */
645	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
646	    }
647	    private final Map<Long, Figures> people;
648	    private final String claimedTotal;
649	    private final String dueTotal;
650	    private final String overdueTotal;
651	    private Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
652	        this.people = people;
653	        this.claimedTotal = claimedTotal;
654	        this.dueTotal = dueTotal;
655	        this.overdueTotal = overdueTotal;
656	    }
657	    /** Works out the sheet's figures now; a sheet not yet stored has none. */
658	    public static Rollup of(String sheetId, SheetRepository sheets, PersonRepository persons,
659	            ClaimRepository claims, RateRepository rates, PersonGradeRepository grades) {
660	        String id = sheetId.trim();
661	        Optional<Sheet> sheet = sheets.findById(id);
662	        Map<Long, Figures> people = new LinkedHashMap<>();
663	        BigDecimal claimedTotal = BigDecimal.ZERO;
664	        BigDecimal dueTotal = BigDecimal.ZERO;
665	        BigDecimal overdueTotal = BigDecimal.ZERO;
666	        if (sheet.isPresent()) {
667	            List<Claim> all = claims.findBySheetIdOrderByIdDesc(id);
668	            var sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(id);
669	            Map<Long, List<PersonGrade>> dated = grades.datedOnSheet(id);
670	            for (Person person : persons.findBySheetIdOrderByIdAsc(id)) {
671	                List<Claim> mine = all.stream().filter(c -> person.getId().equals(c.getPersonId())).toList();
672	                BigDecimal claimed = mine.stream().filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday())).map(Claim::getAmount)
673	                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
674	                ClaimFigures figures = new ClaimFigures(sheetRates,
675	                        new PersonGrades(person.getGrade(), dated.getOrDefault(person.getId(), List.of())), sheet.get());
676	                String due = figures.dueTotal(mine, sheet.get().getToday(), person);
677	                BigDecimal overdue = mine.stream()
678	                        .filter(c -> ClaimFigures.countsLive(c, person, sheet.get().getToday()) && figures.overdue(c))
679	                        .map(figures::due).filter(d -> d != null)
680	                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
681	                people.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), due,
682	                        overdue.toPlainString()));
683	                overdueTotal = overdueTotal.add(overdue);
684	                claimedTotal = claimedTotal.add(claimed);
685	                if (!"n/a".equals(due)) {
686	                    dueTotal = dueTotal.add(new BigDecimal(due));
687	                }
688	            }
689	        }
690	        return new Rollup(people, claimedTotal.setScale(2).toPlainString(), dueTotal.setScale(2).toPlainString(),
691	                overdueTotal.setScale(2).toPlainString());
692	    }
693	    /** The audit lines telling how the figures moved from before to now: one per person whose figures changed
694	     *  (or who is new), then the totals when they changed; none when nothing moved. */
695	    public List<String> changesSince(Rollup before, String sheetId, String user) {
696	        String head = " sheet=" + sheetId.trim() + " by=" + user;
697	        List<String> lines = new ArrayList<>();
698	        people.forEach((id, now) -> {
699	            Figures was = before.people.get(id);
700	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
701	                    || !was.overdueTotal().equals(now.overdueTotal())) {
702	                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
703	                        + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
704	            }
705	        });
706	        if (!before.claimedTotal.equals(claimedTotal) || !before.dueTotal.equals(dueTotal)
707	                || !before.overdueTotal.equals(overdueTotal)) {
708	            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
709	                    + " overdue-total=" + overdueTotal);
710	        }
711	        return lines;
712	    }
713	}
