783	/**
784	 * Reads the paste box from the body: each non-blank line is name,amount,date,note — the note is the rest of the
785	 * line, so it may hold commas; the date and the note may be blank or absent. Checks every line's claim exactly
786	 * as the claim form would (it corrects nothing), refusing the whole paste when any line fails or there is none.
787	 */
788	public class ValidatePaste {
789	    public void validate(@RequestBody PasteRequest request, Out<PastedLines> linesOut) throws InvalidClaimException {
790	        String text = request == null || request.text() == null ? "" : request.text();
791	        List<PastedLine> lines = new ArrayList<>();
792	        int at = 0;
793	        for (String line : text.split("\\r?\\n")) {
794	            at++;
795	            if (line.isBlank()) {
796	                continue;
797	            }
798	            String[] fields = line.split(",", 4);
799	            String name = fields[0].trim();
800	            if (name.isEmpty() || fields.length < 2) {
801	                throw new InvalidClaimException("Line " + at + ": a line is name,amount,date,note.");
802	            }
803	            ClaimInput claim;
804	            try {
805	                claim = ClaimRules.check(fields[1], fields.length > 2 ? fields[2] : null,
806	                        fields.length > 3 ? fields[3] : null, null);
807	            } catch (InvalidClaimException e) {
808	                throw new InvalidClaimException("Line " + at + ": " + e.getMessage());
809	            }
810	            lines.add(new PastedLine(name, claim));
811	        }
812	        if (lines.isEmpty()) {
813	            throw new InvalidClaimException("Paste at least one line of name,amount,date,note.");
814	        }
